exec('\nfrom __future__ import annotations\nimport time, warnings, xml.etree.ElementTree as ET\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nimport plotly.graph_objects as go\nimport plotly.express as px\nfrom sklearn.linear_model import Ridge, ElasticNet\nfrom sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, VotingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\nDEFINITIONS = {\n    "ML-only stance": "A paper/research classification generated only from the selected ML model, current features, validation score and confidence. It is not investment advice.",\n    "BUY WATCH": "Model is bullish with enough confidence and acceptable validation. It means research candidate, not an instruction to buy.",\n    "SELL / RISK WATCH": "Model is bearish with enough confidence and acceptable validation. It means risk candidate, not an instruction to sell.",\n    "Neutral / No action": "Model confidence or validation is too weak to treat the signal seriously.",\n    "GCMSI": "Global Critical Materials Stress Index. It combines material, energy, macro and precious-metal shock signals into one stress number.",\n    "Z-score": "A z-score shows how unusual a move is versus recent history. 0 is normal, +2 is unusually high, -2 is unusually low.",\n    "Confidence": "A normalized signal-strength score. It is not a probability.",\n    "Validation quality": "A score based on out-of-sample correlation, number of test rows and whether the model recently aligned with future returns."\n}\n\ndef load_yaml(path, fallback):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            return yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n    except Exception:\n        pass\n    return fallback\n\ndef load_csv(path, fallback):\n    p = ROOT / path\n    try:\n        if p.exists():\n            return pd.read_csv(p).drop_duplicates()\n    except Exception:\n        pass\n    return fallback\n\ndef fallback_exposure():\n    return pd.DataFrame({"asset":["XME","COPX","ITA","XAR","PRNT","SPY"],"full_name":["Mining ETF","Copper miners ETF","Defense ETF","Aerospace ETF","3D Printing ETF","S&P 500 ETF"],"theme":["Mining","Copper","Defense","Aerospace","AM","Market"],"region":["USA","Global","USA","USA","Global","USA"]})\n\nmaterials_cfg = load_yaml("config/materials_universe.yml", {"materials": {}}).get("materials", {})\nindices_cfg = load_yaml("config/global_index_config.yml", {"indices": {}}).get("indices", {})\nmacro_cfg = load_yaml("config/macro_series_config.yml", {"macro_proxies": {}}).get("macro_proxies", {})\ngeo_cfg = load_yaml("config/geopolitical_keywords.yml", {"themes": {}, "default_terms": ["critical minerals","rare earth","war","Iran","oil","gas","gold","silver"]})\nnews_sources = load_yaml("config/news_sources.yml", {"rss_sources": {}}).get("rss_sources", {})\nexposure = load_csv("data/exposure_score_table.csv", fallback_exposure())\ncompany_universe = load_csv("data/manufacturing_company_universe.csv", pd.DataFrame())\n\ndef material_tickers(materials):\n    out = []\n    for spec in materials.values():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        out += [t for t in ticks if t]\n    return out\n\ndef flatten_indices(idx):\n    rows = []\n    for region, mp in idx.items():\n        if isinstance(mp, dict):\n            for name, ticker in mp.items():\n                rows.append({"region": region, "name": name, "ticker": ticker})\n    return pd.DataFrame(rows)\n\ndef safe_period(interval, period):\n    if interval == "1m":\n        return period if period in ["1d", "5d"] else "5d"\n    if interval in ["2m", "5m", "15m", "30m", "60m", "90m"]:\n        return period if period in ["1d", "5d", "1mo"] else "1mo"\n    return period\n\n@st.cache_data(ttl=20, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        pxs = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        pxs = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            pxs.columns = tickers\n    return pxs.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef resolve_materials(prices, materials):\n    resolved, rows = {}, []\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        selected = next((t for t in ticks if t in prices.columns), None)\n        if selected:\n            resolved[name] = selected\n        rows.append({\n            "material": name,\n            "long_name": spec.get("long_name", name) if isinstance(spec, dict) else name,\n            "selected_ticker": selected or "MISSING",\n            "candidate_tickers": ", ".join([str(t) for t in ticks if t]),\n            "family": spec.get("family", "") if isinstance(spec, dict) else "",\n            "role": spec.get("role", "") if isinstance(spec, dict) else "",\n            "proxy_quality": spec.get("proxy_quality", "") if isinstance(spec, dict) else "",\n            "weight": spec.get("weight", .03) if isinstance(spec, dict) else .03\n        })\n    return resolved, pd.DataFrame(rows)\n\ndef zscore(s, window):\n    mean = s.rolling(window, min_periods=max(4, window // 3)).mean()\n    std = s.rolling(window, min_periods=max(4, window // 3)).std()\n    return (s - mean) / std\n\ndef build_features(prices, materials, macro, shock_window):\n    resolved, proxy_table = resolve_materials(prices, materials)\n    f = pd.DataFrame(index=prices.index)\n    meta = []\n    for name, ticker in resolved.items():\n        spec = materials.get(name, {})\n        col = f"MAT:{name}"\n        f[col] = zscore(prices[ticker].pct_change(shock_window), max(10, shock_window * 3))\n        meta.append({"feature": col, "long_name": spec.get("long_name", name), "ticker": ticker, "family": spec.get("family", "material"), "weight": float(spec.get("weight", .03)), "definition": spec.get("role", "")})\n    for name, val in macro.items():\n        ticker = val.get("ticker", val) if isinstance(val, dict) else val\n        if ticker in prices.columns:\n            col = f"MACRO:{name}"\n            f[col] = zscore(prices[ticker].pct_change(shock_window), max(10, shock_window * 3))\n            meta.append({"feature": col, "long_name": name, "ticker": ticker, "family": "macro", "weight": .04, "definition": "macro / market stress proxy"})\n    if f.empty:\n        return f, pd.DataFrame(meta), proxy_table\n    meta_df = pd.DataFrame(meta)\n    weighted, denom = [], 0\n    for _, r in meta_df.iterrows():\n        weighted.append(f[r["feature"]] * float(r["weight"]))\n        denom += float(r["weight"])\n    f["GCMSI"] = sum(weighted) / denom if denom else f.mean(axis=1)\n    for fam in sorted(meta_df["family"].dropna().unique()):\n        cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n        if cols:\n            f[f"FAMILY:{fam}"] = f[cols].mean(axis=1)\n    if "MACRO:VIX" in f.columns:\n        f["REGIME:RiskOff"] = (f["GCMSI"] + f["MACRO:VIX"]) / 2\n    if "MACRO:USDIndex" in f.columns:\n        f["REGIME:USDPressure"] = (f["GCMSI"] + f["MACRO:USDIndex"]) / 2\n    return f.replace([np.inf, -np.inf], np.nan).dropna(), meta_df, proxy_table\n\ndef plot_lines(df, title, ytitle="Value", normalize=False):\n    if df.empty:\n        st.warning("No data.")\n        return\n    x = df.copy().ffill().dropna(how="all")\n    if normalize and len(x):\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for col in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[col], mode="lines", name=str(col), hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, xaxis_title="Time", yaxis_title=ytitle, legend_title="Ticker / signal", hovermode="x unified", height=440)\n    st.plotly_chart(fig, use_container_width=True)\n\ndef plot_bar(series, title):\n    s = series.dropna().sort_values()\n    fig = px.bar(x=s.values, y=s.index, orientation="h", title=title, labels={"x": "Value", "y": "Element / signal"})\n    fig.update_layout(height=max(380, 24 * len(s)))\n    st.plotly_chart(fig, use_container_width=True)\n\n@st.cache_data(ttl=240, show_spinner=False)\ndef gdelt(query, max_records):\n    try:\n        r = requests.get("https://api.gdeltproject.org/api/v2/doc/doc", params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": max_records, "sort": "HybridRel"}, timeout=12)\n        if r.status_code != 200:\n            return pd.DataFrame()\n        return pd.DataFrame([{"title": a.get("title", ""), "source": "GDELT / " + a.get("domain", ""), "country": a.get("sourceCountry", ""), "date": a.get("seendate", ""), "url": a.get("url", "")} for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef rss_fetch(sources, max_per=8):\n    rows = []\n    import xml.etree.ElementTree as ET\n    for name, spec in sources.items():\n        url = spec.get("url", "") if isinstance(spec, dict) else str(spec)\n        focus = spec.get("focus", "") if isinstance(spec, dict) else ""\n        try:\n            r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab/1.0"})\n            if r.status_code != 200:\n                continue\n            root = ET.fromstring(r.content)\n            items = root.findall(".//item")[:max_per]\n            for it in items:\n                rows.append({"title": (it.findtext("title") or "").strip(), "source": name, "country": "", "date": (it.findtext("pubDate") or "").strip(), "url": (it.findtext("link") or "").strip(), "focus": focus})\n        except Exception:\n            continue\n    return pd.DataFrame(rows)\n\ndef score_news(news, geo_cfg):\n    if news.empty:\n        return 0.0, pd.DataFrame()\n    titles = " ".join(news["title"].fillna("").astype(str)).lower()\n    rows, score = [], 0\n    for theme, spec in geo_cfg.get("themes", {}).items():\n        words = spec.get("words", []) if isinstance(spec, dict) else spec\n        weight = float(spec.get("weight", 1)) if isinstance(spec, dict) else 1\n        long_name = spec.get("long_name", theme) if isinstance(spec, dict) else theme\n        count = sum(titles.count(str(w).lower()) for w in words)\n        rows.append({"theme": theme, "long_name": long_name, "mentions": count, "weighted_score": count * weight})\n        score += count * weight\n    return min(score / 14, 4.0), pd.DataFrame(rows).sort_values("weighted_score", ascending=False)\n\ndef model_obj(name):\n    if name == "ElasticNet":\n        return ElasticNet(alpha=.01, l1_ratio=.2, random_state=42)\n    if name == "RandomForest":\n        return RandomForestRegressor(n_estimators=220, max_depth=5, random_state=42)\n    if name == "ExtraTrees":\n        return ExtraTreesRegressor(n_estimators=250, max_depth=5, random_state=42)\n    if name == "GradientBoosting":\n        return GradientBoostingRegressor(random_state=42, max_depth=3)\n    if name == "Ensemble":\n        return VotingRegressor([("ridge", Ridge(alpha=8)), ("rf", RandomForestRegressor(n_estimators=140, max_depth=4, random_state=42)), ("gb", GradientBoostingRegressor(random_state=42, max_depth=2))])\n    return Ridge(alpha=8)\n\ndef final_ml_stance(signal, confidence, test_corr, test_rows):\n    validation_ok = (test_corr > 0.03 and test_rows >= 5)\n    validation_weak = (test_corr <= 0.03 or test_rows < 5)\n    if confidence >= .66 and validation_ok:\n        return "ML-only BUY WATCH" if signal == "Bullish" else "ML-only SELL / RISK WATCH"\n    if confidence >= .33 and test_corr > -0.05:\n        return "ML-only BULLISH WATCH" if signal == "Bullish" else "ML-only BEARISH WATCH"\n    if validation_weak:\n        return "NO ACTION — validation weak"\n    return "NEUTRAL / NO ACTION"\n\ndef train_one(asset, prices, features, requested_horizon, model_name, feat_cols):\n    if asset not in prices.columns:\n        return None, None, "no price"\n    available_rows = int(prices[asset].dropna().shape[0])\n    effective_horizon = max(1, min(int(requested_horizon), max(1, available_rows // 8)))\n    y = prices[asset].pct_change(effective_horizon).shift(-effective_horizon).rename("future_return")\n    df = pd.concat([features[feat_cols], y], axis=1, join="inner").dropna()\n    if len(df) < 20:\n        effective_horizon = 1\n        y = prices[asset].pct_change(1).shift(-1).rename("future_return")\n        df = pd.concat([features[feat_cols], y], axis=1, join="inner").dropna()\n    if len(df) < 16:\n        return None, None, "not enough rows"\n    split = max(10, int(len(df) * .70))\n    if split >= len(df) - 3:\n        split = max(8, len(df) - 5)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 3:\n        return None, None, "too few test rows"\n    Xtr, ytr = tr[feat_cols].fillna(0), tr["future_return"].astype(float)\n    Xte, yte = te[feat_cols].fillna(0), te["future_return"].astype(float)\n    model = model_obj(model_name)\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    latest_pred = float(model.predict(features.iloc[[-1]][feat_cols].fillna(0))[0])\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred) ** .5)\n    vol = max(float(ytr.std()), 1e-6)\n    confidence = min(abs(latest_pred) / (vol * 1.25), 1)\n    signal = "Bullish" if latest_pred > 0 else "Bearish"\n    intensity = "Strong" if confidence > .66 else "Moderate" if confidence > .33 else "Weak"\n    if hasattr(model, "feature_importances_"):\n        imp = pd.Series(model.feature_importances_, index=feat_cols).sort_values(ascending=False)\n    elif hasattr(model, "coef_"):\n        imp = pd.Series(np.abs(model.coef_), index=feat_cols).sort_values(ascending=False)\n    else:\n        imp = pd.Series(0, index=feat_cols)\n    te2 = te.copy()\n    te2["prediction"] = pred\n    te2["position"] = np.where(te2["prediction"] > 0, 1, -1)\n    te2["strategy_return_net"] = te2["position"] * te2["future_return"] - .0005 * pd.Series(te2["position"], index=te2.index).diff().abs().fillna(1)\n    te2["equity_net"] = (1 + te2["strategy_return_net"].fillna(0)).cumprod()\n    dd = float((te2["equity_net"] / te2["equity_net"].cummax() - 1).min())\n    stance = final_ml_stance(signal, confidence, corr, len(te))\n    score = float((1 if signal == "Bullish" else -1) * confidence * max(min(corr + .25, 1), 0))\n    reason = f"{signal} pressure because latest predicted return is {latest_pred:.5f}; main model drivers are {imp.index[0] if len(imp)>0 else \'N/A\'}, {imp.index[1] if len(imp)>1 else \'N/A\'}, {imp.index[2] if len(imp)>2 else \'N/A\'}."\n    validation = "Acceptable" if corr > .03 and len(te) >= 5 else "Weak"\n    row = {\n        "asset": asset,\n        "signal": signal,\n        "final_ml_stance": stance,\n        "bull_bear_score": score,\n        "intensity": intensity,\n        "prediction": latest_pred,\n        "confidence": confidence,\n        "test_corr": corr,\n        "validation_quality": validation,\n        "rmse": rmse,\n        "max_drawdown_toy": dd,\n        "requested_horizon": requested_horizon,\n        "effective_horizon": effective_horizon,\n        "train_rows": len(tr),\n        "test_rows": len(te),\n        "driver_1": imp.index[0] if len(imp) > 0 else "",\n        "driver_2": imp.index[1] if len(imp) > 1 else "",\n        "driver_3": imp.index[2] if len(imp) > 2 else "",\n        "ml_reason": reason,\n        "final_message": f"{stance}: {reason} Validation is {validation}. This is an ML-only research label, not financial advice."\n    }\n    return row, te2, None\n\n@st.cache_data(ttl=120, show_spinner=False)\ndef options_chain(ticker, expiry=None):\n    try:\n        tk = yf.Ticker(ticker)\n        expiries = list(tk.options)\n        if not expiries:\n            return expiries, pd.DataFrame(), pd.DataFrame()\n        exp = expiry if expiry in expiries else expiries[0]\n        ch = tk.option_chain(exp)\n        return expiries, ch.calls.copy(), ch.puts.copy()\n    except Exception:\n        return [], pd.DataFrame(), pd.DataFrame()\n\ndef make_query(terms):\n    clean = [x.strip() for x in terms if x.strip()]\n    return "(" + " OR ".join(clean) + ")" if clean else "(critical minerals OR rare earth)"\n\ndef regime(latest, gscore):\n    gc = latest.get("GCMSI", 0)\n    vix = latest.get("MACRO:VIX", 0)\n    usd = latest.get("MACRO:USDIndex", 0)\n    energy = latest.get("FAMILY:energy_inputs", 0)\n    if gscore >= 2.5 and gc > .4:\n        return "Geopolitical materials shock"\n    if gc > 1.2 and vix > .8:\n        return "Risk-off industrial stress"\n    if energy > 1.1:\n        return "Energy / fuel cost shock"\n    if usd > 1.0 and gc > .3:\n        return "USD commodity pressure"\n    if gc > .8:\n        return "Commodity stress"\n    if gc < -.8:\n        return "Stress easing"\n    return "Normal / mixed"\n\ndef exposure_scores(exposure, latest, gscore):\n    mp = {\n        "copper": latest.get("MAT:Copper", 0),\n        "aluminum": latest.get("MAT:Aluminum", 0),\n        "nickel": latest.get("MAT:Nickel", 0),\n        "steel_chain": latest.get("FAMILY:steel_chain", 0),\n        "battery": latest.get("FAMILY:battery_materials", 0),\n        "rare_earths": latest.get("FAMILY:rare_earths", 0),\n        "energy": latest.get("FAMILY:energy_inputs", 0),\n        "coal": latest.get("MAT:CokingCoal", 0) + latest.get("MAT:ThermalCoal", 0),\n        "uranium": latest.get("MAT:Uranium", 0),\n        "aerospace": latest.get("FAMILY:aerospace_defense_materials", 0),\n        "defense": gscore,\n        "semiconductor": latest.get("FAMILY:electronics_metals", 0) + latest.get("FAMILY:rare_earths", 0),\n        "additive_manufacturing": latest.get("GCMSI", 0),\n        "china_sensitivity": latest.get("MACRO:USDCNY", 0),\n        "geopolitical_sensitivity": gscore,\n        "macro_beta": latest.get("FAMILY:macro", 0)\n    }\n    out = []\n    for _, r in exposure.iterrows():\n        score, den = 0, 0\n        for k, v in mp.items():\n            if k in r and pd.notna(r[k]):\n                score += float(r[k]) * float(v)\n                den += abs(float(r[k]))\n        out.append({"asset": r["asset"], "full_name": r.get("full_name", ""), "theme": r.get("theme", ""), "region": r.get("region", ""), "exposure_adjusted_stress": score / den if den else 0})\n    return pd.DataFrame(out).sort_values("exposure_adjusted_stress", ascending=False)\n\nst.set_page_config(page_title="MatQuantLab V8", layout="wide")\nst.title("MatQuantLab V8 — ML Signal Terminal + Global Manufacturing Universe")\nst.caption("Detailed ML-only bullish/bearish stances, final signal messages, adaptive horizons, and global manufacturing/materials stocks by country.")\n\nidx_df = flatten_indices(indices_cfg)\nmacro_tickers = {k: (v.get("ticker", v) if isinstance(v, dict) else v) for k, v in macro_cfg.items()}\nbase_assets = sorted(set(exposure["asset"].astype(str).tolist() + ["SPY","XME","COPX","ITA","XAR","PRNT","SOXX","XLE","URA","LIT","REMX","SLX","GLD","SLV","USO","UNG"]))\ncompany_assets = sorted(company_universe["ticker"].dropna().astype(str).unique().tolist()) if not company_universe.empty else []\nasset_list = sorted(set(base_assets + company_assets))\ndefaults = [x for x in ["COPX","XME","ITA","XAR","PRNT","SOXX","URA","LIT","REMX","GLD","SLV","SPY"] if x in asset_list]\n\nwith st.sidebar:\n    st.header("Controls")\n    st.write("Best ML-only signal setting: 1d / 6mo or 1y / Ensemble / horizon 5–20.")\n    source_filter = st.radio("Asset universe", ["Core assets", "Manufacturing companies", "Both"], index=2)\n    country_filter = []\n    if not company_universe.empty:\n        countries = sorted(company_universe["country"].dropna().unique().tolist())\n        country_filter = st.multiselect("Filter manufacturing countries", countries, default=[])\n    if source_filter == "Core assets":\n        choices = base_assets\n    elif source_filter == "Manufacturing companies":\n        choices = company_assets\n    else:\n        choices = asset_list\n    if country_filter and not company_universe.empty:\n        country_tickers = company_universe.loc[company_universe["country"].isin(country_filter), "ticker"].astype(str).tolist()\n        choices = sorted(set([x for x in choices if x in country_tickers or x in base_assets]))\n    assets = st.multiselect("Assets to predict", choices, default=[x for x in defaults if x in choices][:12])\n    interval = st.selectbox("Refresh / data interval", ["1m","5m","15m","30m","60m","1d"], index=5)\n    period = st.selectbox("Lookback period", ["1d","5d","1mo","3mo","6mo","1y"], index=4)\n    model_name = st.selectbox("Model", ["Ridge","ElasticNet","RandomForest","ExtraTrees","GradientBoosting","Ensemble"], index=5)\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 10)\n    shock_window = st.slider("Shock window in bars", 3, 100, 20)\n    max_news = st.slider("News items", 10, 120, 60)\n    default_terms = geo_cfg.get("default_terms", ["critical minerals","rare earth","war","Iran","oil","gas","gold","silver"])\n    terms = st.multiselect("Add/remove geopolitical and market terms", sorted(set(default_terms + ["Middle East","Iran","Israel","Red Sea","Houthis","Strait of Hormuz","fuel","gas","LNG","VIX","China","Taiwan","rare earth export controls","semiconductors","uranium","titanium","gold","silver","central bank gold","safe haven"])), default=default_terms)\n    extra = st.text_input("Extra terms, comma separated", value="")\n    if extra:\n        terms += [x.strip() for x in extra.split(",") if x.strip()]\n    auto = st.toggle("Auto-refresh", value=False)\n    seconds = st.selectbox("Auto-refresh seconds", [20,30,60,120,300], index=2)\n    if st.button("Force refresh"):\n        st.cache_data.clear()\n        st.rerun()\n\nif auto:\n    time.sleep(seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nperiod = safe_period(interval, period)\nquery = make_query(terms)\ntickers = sorted(set(assets + material_tickers(materials_cfg) + list(macro_tickers.values()) + idx_df.get("ticker", pd.Series(dtype=str)).dropna().tolist() + ["GLD","SLV","USO","UNG"]))\nprices = download_prices(tickers, period, interval)\nif prices.empty:\n    st.error("No prices downloaded. Try daily interval and 6mo/1y.")\n    st.stop()\n\nfeatures, meta, proxy_table = build_features(prices, materials_cfg, macro_tickers, shock_window)\nif features.empty:\n    st.error("No features built. Try daily interval and longer lookback.")\n    st.stop()\n\ngd = gdelt(query, max_news)\nrss = rss_fetch(news_sources, max_per=8)\nnews = pd.concat([gd, rss], ignore_index=True) if not gd.empty or not rss.empty else pd.DataFrame()\ngscore, gthemes = score_news(news, geo_cfg)\nlatest = features.iloc[-1]\nreg = regime(latest, gscore)\nfeat_cols = [c for c in features.columns if c.startswith(("MAT:","MACRO:","FAMILY:","REGIME:")) or c == "GCMSI"]\n\npred_rows, curves = [], {}\nfor a in assets:\n    row, curve, err = train_one(a, prices, features, horizon, model_name, feat_cols)\n    if row:\n        exp = exposure.loc[exposure["asset"].astype(str) == a]\n        comp = company_universe.loc[company_universe["ticker"].astype(str) == a] if not company_universe.empty else pd.DataFrame()\n        if len(exp):\n            row["full_name"] = exp.iloc[0].get("full_name", "")\n            row["theme"] = exp.iloc[0].get("theme", "")\n            row["country"] = exp.iloc[0].get("region", "")\n            row["industry_group"] = row["theme"]\n        if len(comp):\n            row["full_name"] = comp.iloc[0].get("company", row.get("full_name", ""))\n            row["theme"] = comp.iloc[0].get("material_link", row.get("theme", ""))\n            row["country"] = comp.iloc[0].get("country", row.get("country", ""))\n            row["industry_group"] = comp.iloc[0].get("industry_group", "")\n        pred_rows.append(row)\n        curves[a] = curve\n\npred = pd.DataFrame(pred_rows).sort_values(["confidence","test_corr"], ascending=[False,False]) if pred_rows else pd.DataFrame()\n\nc1,c2,c3,c4,c5,c6 = st.columns(6)\nc1.metric("GCMSI", f"{latest.get(\'GCMSI\',0):.2f}", help=DEFINITIONS["GCMSI"])\nc2.metric("Stress regime", reg)\nc3.metric("Geo/news risk", f"{gscore:.2f}")\nc4.metric("Tickers loaded", prices.shape[1])\nc5.metric("Predictions", len(pred))\nc6.metric("Companies in universe", len(company_universe) if not company_universe.empty else 0)\nst.info("Important: BUY/SELL words in this app are ML-only research labels. They are not investment advice or trade instructions.")\n\ntabs = st.tabs([\n    "ML Signal Summary",\n    "Detailed Prediction",\n    "Manufacturing Universe",\n    "Radar",\n    "Options & Contracts",\n    "News",\n    "Gold/Silver",\n    "Exposure Matrix",\n    "Raw Data"\n])\n\nwith tabs[0]:\n    st.subheader("ML-only final stance table")\n    st.markdown("""\nThis table gives the final message you asked for, but it is intentionally labeled **ML-only**.\n\n- **ML-only BUY WATCH** = bullish model pressure + enough confidence + acceptable validation.\n- **ML-only SELL / RISK WATCH** = bearish model pressure + enough confidence + acceptable validation.\n- **NO ACTION** = weak confidence or weak validation.\n""")\n    if pred.empty:\n        st.warning("No predictions. Try: interval 1d, lookback 6mo/1y, model Ensemble, horizon 5–20.")\n    else:\n        cols = ["asset","full_name","country","industry_group","final_ml_stance","signal","intensity","bull_bear_score","prediction","confidence","test_corr","validation_quality","driver_1","driver_2","driver_3","effective_horizon","final_message"]\n        st.dataframe(pred[cols], use_container_width=True)\n        st.caption("Sort by confidence and validation_quality. A bullish/bearish label is only useful if validation is acceptable and drivers make economic sense.")\n\nwith tabs[1]:\n    st.subheader("Detailed prediction explainer")\n    if pred.empty:\n        st.warning("No detailed prediction available.")\n    else:\n        chosen = st.selectbox("Choose asset", pred["asset"].tolist())\n        row = pred[pred["asset"] == chosen].iloc[0]\n        st.markdown(f"## {chosen} — {row.get(\'full_name\',\'\')}")\n        st.metric("Final ML-only stance", row["final_ml_stance"])\n        a,b,c,d = st.columns(4)\n        a.metric("Signal", row["signal"])\n        b.metric("Confidence", f"{row[\'confidence\']:.2f}")\n        c.metric("Test correlation", f"{row[\'test_corr\']:.3f}")\n        d.metric("Effective horizon", int(row["effective_horizon"]))\n        st.markdown("### Final message")\n        st.write(row["final_message"])\n        st.markdown("### Why the model says this")\n        st.write(row["ml_reason"])\n        st.markdown("### What would make me distrust it?")\n        st.write("- Validation quality is weak or test correlation is near zero/negative.")\n        st.write("- Top drivers do not make economic/materials sense.")\n        st.write("- The signal is based on very few test rows.")\n        st.write("- News/geopolitical risk contradicts the model.")\n        if chosen in curves:\n            plot_lines(curves[chosen][["prediction","future_return"]], f"{chosen}: ML prediction vs realized future return", "return")\n            plot_lines(curves[chosen][["equity_net"]], f"{chosen}: toy ML-only net equity curve", "equity")\n\nwith tabs[2]:\n    st.subheader("Global manufacturing and materials company universe")\n    st.write("This adds main manufacturing/material companies across major countries. Use the country filter on the left to focus predictions.")\n    if company_universe.empty:\n        st.warning("Company universe file missing.")\n    else:\n        st.dataframe(company_universe, use_container_width=True)\n        counts = company_universe.groupby("country")["ticker"].count().sort_values(ascending=False)\n        plot_bar(counts, "Number of companies by country")\n        st.caption("Tickers are Yahoo/yfinance-style. Some international tickers can fail depending on Yahoo availability, exchange suffix, and data delay.")\n\nwith tabs[3]:\n    st.subheader("Radar")\n    cols = [c for c in ["GCMSI","FAMILY:industrial_metals","FAMILY:steel_chain","FAMILY:battery_materials","FAMILY:rare_earths","FAMILY:aerospace_defense_materials","FAMILY:energy_inputs","FAMILY:precious_stress","FAMILY:precious_industrial","FAMILY:macro","REGIME:RiskOff","REGIME:USDPressure"] if c in features.columns]\n    plot_lines(features[cols], "Global stress radar", "z-score stress")\n    drivers = latest[[c for c in features.columns if c.startswith(("MAT:","MACRO:"))]].sort_values(key=lambda s: s.abs(), ascending=False).head(30)\n    plot_bar(drivers, "Current strongest drivers")\n    st.caption("Z-score: 0 normal, +2 unusually high, -2 unusually low. Use drivers to understand the prediction table.")\n\nwith tabs[4]:\n    st.subheader("Options and contract/proxy monitor")\n    opt_asset = st.selectbox("Options ticker", assets if assets else ["SPY","XME","COPX","ITA","GLD","SLV","USO"])\n    expiries, calls, puts = options_chain(opt_asset)\n    if not expiries:\n        st.warning("No Yahoo options found. Try SPY, XME, COPX, ITA, XLE, GLD, SLV, USO.")\n    else:\n        exp = st.selectbox("Expiration date", expiries)\n        expiries, calls, puts = options_chain(opt_asset, exp)\n        cvol = calls["volume"].fillna(0).sum() if not calls.empty else 0\n        pvol = puts["volume"].fillna(0).sum() if not puts.empty else 0\n        coi = calls["openInterest"].fillna(0).sum() if not calls.empty else 0\n        poi = puts["openInterest"].fillna(0).sum() if not puts.empty else 0\n        a,b,c,d = st.columns(4)\n        a.metric("Call volume", int(cvol))\n        b.metric("Put volume", int(pvol))\n        c.metric("Put/Call volume", f"{pvol/max(cvol,1):.2f}")\n        d.metric("Put/Call OI", f"{poi/max(coi,1):.2f}")\n        st.dataframe(calls[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(40), use_container_width=True)\n        st.dataframe(puts[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(40), use_container_width=True)\n    st.markdown("### Material proxy table")\n    st.dataframe(proxy_table, use_container_width=True)\n\nwith tabs[5]:\n    st.subheader("News terminal")\n    st.write(f"Query: `{query}`")\n    st.metric("Keyword news risk score", f"{gscore:.2f}")\n    st.dataframe(gthemes, use_container_width=True)\n    if not gthemes.empty:\n        plot_bar(gthemes.set_index("long_name")["weighted_score"], "Geopolitical theme intensity")\n    if news.empty:\n        st.warning("No news returned. Remove terms or use a simpler query.")\n    else:\n        st.dataframe(news[["title","source","country","date","url"]].head(100), use_container_width=True)\n\nwith tabs[6]:\n    st.subheader("Gold / silver / precious metals")\n    gs = [t for t in ["GC=F","GLD","SI=F","SLV","PL=F","PPLT","PA=F","PALL"] if t in prices.columns]\n    if gs:\n        plot_lines(prices[gs], "Gold, silver, platinum and palladium proxies", "normalized", normalize=True)\n    pm = [c for c in features.columns if "Gold" in c or "Silver" in c or "Platinum" in c or "Palladium" in c or "precious" in c]\n    if pm:\n        plot_lines(features[pm], "Precious-metal stress signals", "z-score")\n    st.caption("Gold is mostly safe-haven/real-rate/geopolitical. Silver is hybrid: precious metal plus industrial/solar/electronics demand.")\n\nwith tabs[7]:\n    st.subheader("Exposure matrix")\n    st.dataframe(exposure, use_container_width=True)\n    sc = exposure_scores(exposure, latest, gscore)\n    st.dataframe(sc, use_container_width=True)\n    fig = px.bar(sc, x="exposure_adjusted_stress", y="asset", color="theme", orientation="h", title="Exposure-adjusted stress by asset")\n    st.plotly_chart(fig, use_container_width=True)\n\nwith tabs[8]:\n    st.subheader("Raw data")\n    st.dataframe(prices.tail(100), use_container_width=True)\n    st.dataframe(features.tail(100), use_container_width=True)\n    st.dataframe(meta, use_container_width=True)\n\nst.divider()\nst.caption("Data: Yahoo Finance via yfinance + GDELT/RSS. ML-only labels are research outputs, not financial advice.")\n')
